// Original bumbling waltz and telephone effects synthesized locally with Web Audio.
export class LibraryAudio{
 constructor(){this.enabled=true;this.fx=true;this.context=null;this.running=false;this.step=0;this.nextBeat=0;this.nextRing=0;this.nodes=new Set();this.unlocked=false}
 async start(){try{if(!this.context){let Context=window.AudioContext||window.webkitAudioContext;if(!Context)return;this.context=new Context();this.music=this.context.createGain();this.music.gain.value=.19;this.music.connect(this.context.destination);this.effects=this.context.createGain();this.effects.gain.value=.23;this.effects.connect(this.context.destination)}await this.context.resume();this.unlocked=this.context.state==='running'}catch{/* Sound remains optional when browser autoplay is restricted. */}}
 tone(freq,at,duration,type='triangle',volume=.4,detune=0,fx=false){if(!this.context||!this.unlocked)return;let ctx=this.context,o=ctx.createOscillator(),g=ctx.createGain(),f=ctx.createBiquadFilter();o.type=type;o.frequency.setValueAtTime(freq,at);o.detune.setValueAtTime(detune,at);f.type='lowpass';f.frequency.value=fx?1800:950;g.gain.setValueAtTime(0,at);g.gain.linearRampToValueAtTime(volume,at+.015);g.gain.exponentialRampToValueAtTime(.001,at+duration);o.connect(f);f.connect(g);g.connect(fx?this.effects:this.music);this.nodes.add(o);o.onended=()=>{this.nodes.delete(o);o.disconnect();g.disconnect();f.disconnect()};o.start(at);o.stop(at+duration+.02)}
 update(running,ringing){if(!this.context||!this.unlocked)return;let now=this.context.currentTime;if(!running){if(this.running)for(let n of this.nodes){try{n.stop()}catch{}}this.running=false;this.nextBeat=now+.05;this.nextRing=now;return}this.running=true;
 if(this.enabled&&now>=this.nextBeat){const melody=[67,71,74,72,69,65,67,64,67,71,74,76,75,69,65,67,72,69,65,64,62,65,67,66,67,74,71,69,65,64,62,60],i=this.step++%melody.length,midi=melody[i],hz=440*2**((midi-69)/12),beat=.39;this.tone(hz,now+.02+(i%7===0?.045:0),.25,'triangle',.30,i%5===0?-19:8);if(i%3===0)this.tone(hz/4,now+.01,.33,'sawtooth',.22,-8);else this.tone(i%2?261.63:329.63,now+.01,.09,'square',.075,11);if(i===12||i===25)this.tone(hz*1.029,now+.11,.12,'sine',.2);this.nextBeat=now+beat+(i===15?.13:0)}
 if(ringing&&this.fx&&now>=this.nextRing){for(let offset of [0,.19,.42,.61]){this.tone(440,now+offset,.14,'square',.15,0,true);this.tone(480,now+offset,.14,'sine',.25,0,true)}this.nextRing=now+2.4}if(!ringing)this.nextRing=now
 }
 success(){if(this.fx&&this.context){let t=this.context.currentTime;for(let[i,f]of [523.25,659.25,783.99].entries())this.tone(f,t+i*.07,.15,'triangle',.17,0,true)}}
 failure(){if(this.fx&&this.context){let t=this.context.currentTime;this.tone(196,t,.24,'sawtooth',.20,-12,true);this.tone(146.83,t+.18,.35,'triangle',.23,-17,true)}}
}
